<?php declare(strict_types=1);require_once dirname(__DIR__,2).'/security.php';$editing=!empty($task['id']);$canAssign=$role!=='Faculty';?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $editing?'Edit':'Create' ?> task</title><link rel="stylesheet" href="/assets/style.css"><style>main{max-width:850px;margin:auto;padding:1rem}.field{margin-bottom:1rem}.field label{display:block;font-weight:700}.field input,.field select,.field textarea{width:100%;max-width:100%;padding:.6rem}.error{color:#9b1c1c}button{min-height:44px}</style></head><body><main id="main-content"><h1><?= $editing?'Edit':'Create' ?> task</h1><?php if($errors):?><div role="alert" tabindex="-1"><h2>Please correct the following</h2><ul><?php foreach($errors as $error):?><li><?=htmlspecialchars($error,ENT_QUOTES)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post"><?=csrfField()?><div class="field"><label for="task_title">Title</label><input id="task_title" name="task_title" required maxlength="255" value="<?=htmlspecialchars((string)($task['task_title']??''),ENT_QUOTES)?>" <?=!$canAssign?'readonly':''?>></div><div class="field"><label for="task_description">Description</label><textarea id="task_description" name="task_description" rows="5" <?=!$canAssign?'readonly':''?>><?=htmlspecialchars((string)($task['task_description']??''),ENT_QUOTES)?></textarea></div><div class="field"><label for="assigned_user_id">Assigned user</label><select id="assigned_user_id" name="assigned_user_id" <?=!$canAssign?'disabled':''?>><option value="">Unassigned</option><?php foreach($users as $user):?><option value="<?= (int)$user['id']?>" <?=((int)($task['assigned_user_id']??0)===(int)$user['id'])?'selected':''?>><?=htmlspecialchars($user['full_name'].' — '.$user['email'],ENT_QUOTES)?></option><?php endforeach;?></select></div><div class="field"><label for="program_specification_id">Program</label><select id="program_specification_id" name="program_specification_id" <?=!$canAssign?'disabled':''?>><option value="">Unscoped</option><?php foreach($programs as $program):?><option value="<?= (int)$program['id']?>" <?=((int)($task['program_specification_id']??0)===(int)$program['id'])?'selected':''?>><?=htmlspecialchars($program['program_name'],ENT_QUOTES)?></option><?php endforeach;?></select></div><div class="field"><label for="due_date">Due date</label><input id="due_date" type="date" name="due_date" value="<?=htmlspecialchars((string)($task['due_date']??''),ENT_QUOTES)?>"></div><div class="field"><label for="priority">Priority</label><select id="priority" name="priority"><?php foreach(['Low','Medium','High'] as $value):?><option <?=($task['priority']??'Medium')===$value?'selected':''?>><?=$value?></option><?php endforeach;?></select></div><div class="field"><label for="status">Status</label><select id="status" name="status"><?php foreach(['Pending','In Progress','Completed','Cancelled'] as $value):?><option <?=($task['status']??'Pending')===$value?'selected':''?>><?=$value?></option><?php endforeach;?></select></div><div class="field"><label for="notes">Notes</label><textarea id="notes" name="notes" rows="4"><?=htmlspecialchars((string)($task['notes']??''),ENT_QUOTES)?></textarea></div><button type="submit">Save task</button> <a href="/tasks">Cancel</a></form></main></body></html>
